#!/usr/bin/env python3
"""Microstructure measures on synthetic tick streams whose answers are known.

Every estimator below is scored against the value that was planted, which is
the only way to know whether a measure works before it meets real data:

    part 1  bars      - time vs tick vs volume vs dollar bars at MATCHED bar
                        counts, in two worlds: variance arriving WITH trades
                        (the mixture-of-distributions story) and variance
                        arriving ON THE CLOCK (news, jumps). Which world you are
                        in decides whether bar choice does anything.
    part 2  sides     - Lee-Ready / tick rule / EMO / bulk-volume classification
                        against the TRUE initiator, under exchange timestamps and
                        under a vendor clock that stamps trades late, with
                        0 / 1 / 5 second quote lags
    part 3  spreads   - quoted, effective, realized, and price impact
                        (= effective - realized) by trade size
    part 4  impact    - Kyle's lambda by regression (planted value recovered),
                        what classification error does to it, order-flow
                        imbalance (OFI), Amihud illiquidity, VPIN mechanics

Two generators share one price mechanism - a fundamental value with PLANTED
linear permanent impact (lambda $/share, cycling by day), news noise in clock
time, U-shaped and bursty arrivals, autocorrelated order flow:

    simulate_book()   10 sessions with a market maker who re-centres tick-rounded
                      quotes after a few ms, trades at the touch / midpoint /
                      price-improved / walking the book, and a vendor clock with
                      a heavy-tailed reporting delay. Used by parts 2-4.
    simulate_trades() 40 sessions, vectorised, trades only. Used by part 1 and
                      for the Amihud/Kyle rank test in part 4.

Nothing is tuned to look dramatic; the honest sizes are printed with caveats.

Run:  python microstructure_measures.py
numpy + pandas only, fixed seed, ASCII output. About 20 seconds.
"""
from __future__ import annotations

import math

import numpy as np
import pandas as pd

SEED = 20260908
TICK = 0.01
BPS = 1e4
SESSION = 23400.0                  # 09:30-16:00 in seconds
N_DAYS_BOOK = 10
N_DAYS_TRADES = 40
LAMBDAS = np.array([0.5, 1.5, 2.5, 1.0, 2.0]) * 1e-5     # planted $/share, cycling by day
PERSIST = 0.7                      # P(next trade has the same initiator side)
DEPTH_PER_LEVEL = 800              # shares resting at each level beyond the touch
LATENCY_MS = 3.0                   # median ms from a trade to the re-centred quote
DELAY_MS = 80.0                    # median ms the vendor clock stamps trades late


def _u_shape(t):
    """Intraday activity multiplier: ~3.5 at the open/close, ~1 at midday."""
    return 1.0 + 2.5 * (np.exp(-t / 1800.0) + np.exp(-(SESSION - t) / 1800.0))


def _half_spread(t):
    return TICK * (0.35 + 0.45 * (_u_shape(t) - 1.0) / 2.5)


def _recentre(v: float, t: float) -> tuple[float, float]:
    u = 1.0 + 2.5 * (math.exp(-t / 1800.0) + math.exp(-(SESSION - t) / 1800.0))
    h = TICK * (0.35 + 0.45 * (u - 1.0) / 2.5)
    bid = math.floor((v - h) / TICK + 1e-9) * TICK
    ask = math.ceil((v + h) / TICK - 1e-9) * TICK
    if ask <= bid + 1e-12:
        ask = bid + TICK
    return round(bid, 4), round(ask, 4)


def _arrivals(rng, day_factor: float):
    """U-shaped, bursty trade arrival times for one session, by thinning."""
    nb = int(SESSION // 60) + 1
    lb = np.zeros(nb)
    eps = rng.normal(0.0, 0.45, nb)
    for k in range(1, nb):
        lb[k] = 0.8 * lb[k - 1] + eps[k]
    burst = np.exp(lb - lb.var() / 2.0)
    base = 0.55 * day_factor
    rate_max = base * 3.6 * float(burst.max())
    cand = np.sort(rng.uniform(0.0, SESSION, rng.poisson(rate_max * SESSION)))
    rate = base * _u_shape(cand) * burst[(cand // 60).astype(int)]
    return cand[rng.uniform(0.0, 1.0, len(cand)) < rate / rate_max]


def _sizes(rng, n: int):
    odd = rng.integers(1, 100, n).astype(float)
    lots = 100.0 * np.maximum(1, np.round(np.exp(rng.normal(5.4, 0.9, n)) / 100.0))
    return np.where(rng.uniform(0.0, 1.0, n) < 0.3, odd, lots)


def _sides(rng, n: int):
    flip = np.where(rng.uniform(0.0, 1.0, n) < PERSIST, 1.0, -1.0)
    return float(rng.choice([-1.0, 1.0])) * np.cumprod(flip)


# --------------------------------------------------- generator 1: trades ---
def simulate_trades(n_days: int, seed: int, lam_scale: float, news_daily: float,
                    jump_rate: float, jump_sd: float) -> dict:
    """Vectorised trades-only stream. Returns trades and the variance split."""
    rng = np.random.default_rng(seed)
    cols = {k: [] for k in ("t", "day", "px", "sz", "side")}
    ss_imp = ss_news = 0.0
    lam_by_day = []
    v = 100.0
    for d in range(n_days):
        lam = float(LAMBDAS[d % len(LAMBDAS)]) * lam_scale
        lam_by_day.append(lam)
        v *= math.exp(rng.normal(0.0, 0.006))
        tt = _arrivals(rng, rng.lognormal(0.0, 0.35))
        n = len(tt)
        side = _sides(rng, n); size = _sizes(rng, n)
        imp = lam * side * size
        dt = np.diff(tt, prepend=0.0)
        news = news_daily * v / math.sqrt(SESSION) * np.sqrt(dt) * rng.normal(0.0, 1.0, n)
        jt = rng.uniform(0.0, SESSION, rng.poisson(jump_rate))
        jidx = np.searchsorted(tt, jt)
        jumps = np.zeros(n)
        keep = jidx < n
        np.add.at(jumps, jidx[keep], v * rng.normal(0.0, jump_sd, int(keep.sum())))
        path = v + np.cumsum(imp + news + jumps)
        h = _half_spread(tt)
        px = np.where(side > 0, np.ceil((path + h) / TICK - 1e-9),
                      np.floor((path - h) / TICK + 1e-9)) * TICK
        cols["t"].append(d * 86400.0 + tt); cols["day"].append(np.full(n, d))
        cols["px"].append(np.round(px, 4)); cols["sz"].append(size); cols["side"].append(side)
        ss_imp += float(imp.sum()) ** 2; ss_news += float((news + jumps).sum()) ** 2
        v = float(path[-1])
    trades = pd.DataFrame({k: np.concatenate(x) for k, x in cols.items()})
    return {"trades": trades, "trade_var_share": ss_imp / (ss_imp + ss_news),
            "lambdas": np.array(lam_by_day)}


# ----------------------------------------------------- generator 2: book ---
def simulate_book(n_days: int = N_DAYS_BOOK, seed: int = SEED) -> dict:
    rng = np.random.default_rng(seed)
    T_parts, Q_parts = [], []
    v = 100.0

    def depth() -> float:
        return max(100.0, 100.0 * round(math.exp(rng.normal(6.6, 0.6)) / 100.0))

    for d in range(n_days):
        lam = float(LAMBDAS[d % len(LAMBDAS)])
        v *= math.exp(rng.normal(0.0, 0.006))
        sigma_news = 0.003 * v / math.sqrt(SESSION)
        trade_times = _arrivals(rng, rng.lognormal(0.0, 0.35))
        quote_times = np.sort(rng.uniform(0.0, SESSION, rng.poisson(1.0 * SESSION)))
        jump_times = np.sort(rng.uniform(0.0, SESSION, rng.poisson(2)))
        ev_t = np.concatenate([quote_times, trade_times, jump_times])
        ev_k = np.concatenate([np.zeros(len(quote_times), int), np.ones(len(trade_times), int),
                               np.full(len(jump_times), 2)])
        order = np.argsort(ev_t, kind="stable")
        ev_t, ev_k = ev_t[order], ev_k[order]
        n_ev = len(ev_t)

        z_news = rng.normal(0.0, 1.0, n_ev)
        u_side = rng.uniform(0.0, 1.0, n_ev)
        u_loc = rng.uniform(0.0, 1.0, n_ev)
        sizes = _sizes(rng, n_ev)
        latency = np.exp(rng.normal(math.log(LATENCY_MS / 1e3), 0.5, n_ev))
        delay = np.exp(rng.normal(math.log(DELAY_MS / 1e3), 1.0, n_ev))    # fat tail
        jump = rng.normal(0.0, 0.002, n_ev)
        u_depth = rng.uniform(0.0, 1.0, n_ev)

        # preallocated output: trades (7 cols) and quotes (5 cols), filled by index
        nT = len(trade_times); T = np.zeros((nT, 7)); iT = 0
        Q = np.zeros((n_ev + 1, 5)); iQ = 0
        bid, ask = _recentre(v, 0.0)
        bsz, asz = depth(), depth()
        Q[iQ] = (d * 86400.0, bid, ask, bsz, asz); iQ += 1
        last_t = 0.0
        prev_side = 1.0 if rng.uniform() < 0.5 else -1.0
        day_off = d * 86400.0

        for i in range(n_ev):
            t = ev_t[i]; k = ev_k[i]
            v += sigma_news * math.sqrt(t - last_t) * z_news[i]
            last_t = t
            if k == 2:                                   # news jump
                v *= math.exp(jump[i])
                bid, ask = _recentre(v, t)
                Q[iQ] = (day_off + t + latency[i], bid, ask, bsz, asz); iQ += 1
                continue
            if k == 0:                                   # background quote refresh
                if u_depth[i] < 0.5:
                    bsz = depth()
                else:
                    asz = depth()
                bid, ask = _recentre(v, t)
                Q[iQ] = (day_off + t, bid, ask, bsz, asz); iQ += 1
                continue

            # ---- a trade, with a KNOWN initiator ---------------------------
            side = prev_side if u_side[i] < PERSIST else -prev_side
            prev_side = side
            size = sizes[i]
            mid = 0.5 * (bid + ask)
            spread_ticks = int(round((ask - bid) / TICK))
            touch = ask if side > 0 else bid
            touch_sz = asz if side > 0 else bsz
            if size > touch_sz:                          # walks the book
                extra = min(3, int(math.ceil((size - touch_sz) / DEPTH_PER_LEVEL)))
                price, loc = touch + side * extra * TICK, 3
            elif u_loc[i] < 0.80:
                price, loc = touch, 0
            elif u_loc[i] < 0.90:
                price, loc = mid, 1                      # midpoint execution
            elif spread_ticks >= 2:
                price, loc = touch - side * TICK, 2      # price-improved inside the spread
            else:
                price, loc = touch, 0
            T[iT] = (day_off + t, d, round(price, 4), size, side, loc, delay[i]); iT += 1

            v += lam * side * size                       # planted permanent impact
            if side > 0:
                asz = asz - size if size < asz else depth()
            else:
                bsz = bsz - size if size < bsz else depth()
            bid, ask = _recentre(v, t)                   # market maker re-centres ...
            Q[iQ] = (day_off + t + latency[i], bid, ask, bsz, asz); iQ += 1   # ... ms later
        T_parts.append(T[:iT]); Q_parts.append(Q[:iQ])

    T = np.vstack(T_parts); Q = np.vstack(Q_parts)
    trades = pd.DataFrame(T, columns=["t", "day", "px", "sz", "side", "loc", "delay"])
    trades["day"] = trades["day"].astype(int); trades["loc"] = trades["loc"].astype(int)
    quotes = pd.DataFrame(Q, columns=["t", "bid", "ask", "bsz", "asz"]).sort_values("t", kind="stable")
    trades["t_vendor"] = trades["t"] + trades["delay"]
    return {"trades": trades, "quotes": quotes.reset_index(drop=True),
            "lambdas": np.array([float(LAMBDAS[d % len(LAMBDAS)]) for d in range(n_days)])}


# ---------------------------------------------------------------- helpers ---
def prevailing(quote_t: np.ndarray, at: np.ndarray, lag: float = 0.0) -> np.ndarray:
    """Index of the last quote STRICTLY before (at - lag); -1 when there is none."""
    return np.searchsorted(quote_t, at - lag, side="left") - 1


def tick_rule(px: np.ndarray) -> np.ndarray:
    """+1 on an uptick, -1 on a downtick; zero ticks carry the previous sign."""
    d = np.sign(np.diff(px, prepend=px[0]))
    out = np.zeros(len(px))
    s = 0.0
    for i in range(len(px)):
        if d[i] != 0:
            s = d[i]
        out[i] = s
    return out


def moments(r: np.ndarray) -> dict:
    r = r[np.isfinite(r)]
    z = (r - r.mean()) / r.std()
    skew = float(np.mean(z ** 3)); kurt = float(np.mean(z ** 4) - 3.0)
    n = len(r)
    z2 = z ** 2
    return {"n": n, "skew": skew, "exkurt": kurt, "jb": n / 6.0 * (skew ** 2 + kurt ** 2 / 4.0),
            "tail3": float(np.mean(np.abs(z) > 3.0)),
            "ac_r2": float(np.corrcoef(z2[:-1], z2[1:])[0, 1])}


def norm_cdf(x: np.ndarray) -> np.ndarray:
    return 0.5 * (1.0 + np.vectorize(math.erf)(x / math.sqrt(2.0)))


def ols(y: np.ndarray, x: np.ndarray) -> tuple[float, float, float]:
    """slope, its standard error, and R^2 for y = a + b x."""
    x = x - x.mean(); yc = y - y.mean()
    b = float((x * yc).sum() / (x * x).sum())
    resid = yc - b * x
    se = math.sqrt(float((resid ** 2).sum() / (len(y) - 2) / (x * x).sum()))
    return b, se, 1.0 - float((resid ** 2).sum() / (yc ** 2).sum())


def session_bar_ids(weight: np.ndarray, day: np.ndarray, thr: float, n_days: int) -> np.ndarray:
    """Threshold bars; the cumulative weight restarts every session so no bar spans a night."""
    ids = np.zeros(len(weight), dtype=np.int64)
    base = 0
    for d in range(n_days):
        m = day == d
        c = np.cumsum(weight[m]) - weight[m]               # weight BEFORE this trade
        ids[m] = base + (c // thr).astype(np.int64)
        base = int(ids[m].max()) + 1
    return ids


# ------------------------------------------------------------------ part 1 ---
def bar_table(trades: pd.DataFrame, n_days: int) -> dict:
    t = trades["t"].to_numpy(); day = trades["day"].to_numpy()
    px = trades["px"].to_numpy(); sz = trades["sz"].to_numpy()
    tod = t - day * 86400.0
    n_time = int(SESSION // 60) * n_days                     # 1-minute bars
    thr_tick = round(len(trades) / n_time)
    thr_vol = round(sz.sum() / n_time)
    thr_dol = round((sz * px).sum() / n_time)
    kinds = {
        "time 1-min": day * 1000 + (tod // 60).astype(np.int64),
        f"tick ({thr_tick} trades)": session_bar_ids(np.ones(len(px)), day, thr_tick, n_days),
        f"volume ({thr_vol:,} sh)": session_bar_ids(sz, day, thr_vol, n_days),
        f"dollar (${thr_dol / 1e6:.2f}M)": session_bar_ids(sz * px, day, thr_dol, n_days),
    }
    print(f"  {'bar type':<24}{'bars':>7}{'bars/day':>12}{'skew':>7}{'ex.kurt':>9}"
          f"{'JB':>10}{'|z|>3':>8}{'ac(r2)':>8}{'var ratio':>11}")
    print("  " + "-" * 96)
    out = {}
    for name, ids in kinds.items():
        g = pd.DataFrame({"id": ids, "px": px, "t": t, "day": day}).groupby("id", sort=True)
        close = g["px"].last().to_numpy(); tend = g["t"].last().to_numpy()
        bday = g["day"].last().to_numpy()
        same = bday[1:] == bday[:-1]
        r = np.diff(np.log(close))[same]; tend = tend[1:][same]; rday = bday[1:][same]
        m = moments(r)
        hh = ((tend - rday * 86400.0) // 1800).astype(int)   # half-hour of the day
        var_hh = pd.Series(r ** 2).groupby(hh).mean()
        m["ratio"] = float(var_hh.max() / var_hh.min())
        per_day = pd.Series(ids).groupby(day).nunique()
        m["per_day"] = (int(per_day.min()), int(per_day.max()))
        out[name] = m
        print(f"  {name:<24}{len(close):>7,}{per_day.min():>5}-{per_day.max():<6}"
              f"{m['skew']:>7.2f}{m['exkurt']:>9.2f}{m['jb']:>10,.0f}{m['tail3']:>8.3%}"
              f"{m['ac_r2']:>8.2f}{m['ratio']:>11.1f}")
    return out


def part1_bars() -> dict:
    print("PART 1  bars: time vs tick vs volume vs dollar, at MATCHED bar counts")
    print("-" * 78)
    worlds = {
        "A. variance arrives WITH trades": dict(lam_scale=1.0, news_daily=0.0015,
                                                jump_rate=1.0, jump_sd=0.0015),
        "B. variance arrives ON THE CLOCK": dict(lam_scale=0.4, news_daily=0.005,
                                                 jump_rate=4.0, jump_sd=0.003),
    }
    res = {}
    for label, kw in worlds.items():
        sim = simulate_trades(N_DAYS_TRADES, SEED, **kw)
        tr = sim["trades"]
        px = tr["px"].to_numpy()
        print(f"\n  {label}: {len(tr):,} trades, {N_DAYS_TRADES} sessions,"
              f" {sim['trade_var_share']:.0%} of daily variance from trades,"
              f" price range {px.min():.2f}-{px.max():.2f}")
        res[label] = bar_table(tr, N_DAYS_TRADES)
        if label.startswith("A"):
            res["_streamA"] = sim
    print("\n  Gaussian reference: ex.kurt 0, |z|>3 0.270%, JB ~ 0-6, ac(r2) ~ 0.")
    print("  var ratio = max/min of mean squared bar return across the 13 half-hours (1 = the")
    print("  clock is even); bars/day = min-max count per session at one fixed threshold.")
    a = res["A. variance arrives WITH trades"]; b = res["B. variance arrives ON THE CLOCK"]
    na, nb = list(a), list(b)
    ka = [a[n]["exkurt"] for n in na]; kb = [b[n]["exkurt"] for n in nb]
    ta = [a[n]["tail3"] for n in na]; tb = [b[n]["tail3"] for n in nb]
    print(f"\n  World A: excess kurtosis {ka[0]:.2f} (time) -> {ka[1]:.2f} / {ka[2]:.2f} / {ka[3]:.2f}"
          f" (tick / volume / dollar);")
    print(f"           half-hour variance ratio {a[na[0]]['ratio']:.1f} -> {a[na[1]]['ratio']:.1f} /"
          f" {a[na[2]]['ratio']:.1f} / {a[na[3]]['ratio']:.1f}; |z|>3 {ta[0]:.2%} -> {ta[1]:.2%} /"
          f" {ta[2]:.2%} / {ta[3]:.2%}.")
    print(f"  World B: excess kurtosis {kb[0]:.2f} (time) -> {kb[1]:.2f} / {kb[2]:.2f} / {kb[3]:.2f};"
          f" |z|>3 {tb[0]:.2%} -> {tb[1]:.2%} / {tb[2]:.2%} / {tb[3]:.2%}.")
    print("           A kurtosis this size is set by a handful of jump bars, so the four types are")
    print("           within sampling noise of each other. Sampling in activity time evens out the")
    print("           clock; it cannot remove tails that arrive on the clock.")
    print(f"  Dollar vs volume in A: |diff| {abs(ka[3] - ka[2]):.2f} in excess kurtosis. The price"
          f" level moves {(px.max() / px.min() - 1) * 100:.0f}% in 40 sessions,")
    print("  so the two thresholds pick almost the same trades. Dollar bars earn their keep across")
    print("  years and splits, not weeks. The bars/day spread is the cost of any activity bar:")
    print("  sample sizes float, and a threshold fitted on the whole sample already knows future")
    print("  volume - set it from trailing data.")
    return res


# ------------------------------------------------------------------ part 2 ---
def classify(trades: pd.DataFrame, quotes: pd.DataFrame, ts_col: str, lag: float) -> dict:
    """{rule: predicted side} for one timestamp source and quote lag, in exchange order."""
    at = trades[ts_col].to_numpy()
    order = np.argsort(at, kind="stable")                  # the feed order under THIS clock
    px = trades["px"].to_numpy()[order]
    idx = prevailing(quotes["t"].to_numpy(), at[order], lag)
    ok = idx >= 0
    qb = quotes["bid"].to_numpy(); qa = quotes["ask"].to_numpy()
    bid = np.full(len(px), np.nan); ask = np.full(len(px), np.nan)
    bid[ok] = qb[idx[ok]]; ask[ok] = qa[idx[ok]]
    mid = 0.5 * (bid + ask)
    tick = tick_rule(px)
    quote_rule = np.where(px > mid + 1e-9, 1.0, np.where(px < mid - 1e-9, -1.0, 0.0))
    lee_ready = np.where(quote_rule != 0, quote_rule, tick)
    at_touch = np.isclose(px, bid) | np.isclose(px, ask)
    emo = np.where(at_touch & (quote_rule != 0), quote_rule, tick)
    inv = np.empty_like(order); inv[order] = np.arange(len(order))
    return {"tick rule": tick[inv], "quote rule (mid=unclassified)": quote_rule[inv],
            "Lee-Ready": lee_ready[inv], "EMO": emo[inv]}


def part2_classification(trades: pd.DataFrame, quotes: pd.DataFrame) -> dict:
    print("\n\nPART 2  trade classification against the TRUE initiator")
    print("-" * 78)
    truth = trades["side"].to_numpy(); loc = trades["loc"].to_numpy()
    print(f"  {len(trades):,} trades: {np.mean(loc == 0):.1%} at the touch, {np.mean(loc == 1):.1%}"
          f" at the midpoint, {np.mean(loc == 2):.1%} price-improved inside,"
          f" {np.mean(loc == 3):.1%} walked the book")
    print(f"  quotes re-centre a median {LATENCY_MS:.0f} ms after a trade; the vendor clock stamps"
          f" trades late by median {np.median(trades['delay']) * 1e3:.0f} ms,"
          f" 95th pct {np.percentile(trades['delay'], 95) * 1e3:.0f} ms\n")
    rows = []; keep = {}
    for ts_col, label in (("t", "exchange ts"), ("t_vendor", "vendor ts")):
        for lag in (0.0, 1.0, 5.0):
            preds = classify(trades, quotes, ts_col, lag)
            keep[(label, lag)] = preds["Lee-Ready"]
            for rule, p in preds.items():
                if rule == "tick rule" and lag > 0:
                    continue
                acc = float(np.mean(p == truth))
                by_loc = [float(np.mean(p[loc == j] == truth[loc == j])) for j in range(4)]
                rows.append((label, "-" if rule == "tick rule" else f"{lag:.0f} s", rule, acc, by_loc))
    print(f"  {'clock':<13}{'lag':>5}  {'rule':<30}{'overall':>8}{'touch':>8}{'mid':>8}"
          f"{'inside':>8}{'walked':>8}")
    print("  " + "-" * 88)
    for label, lag, rule, acc, by_loc in rows:
        print(f"  {label:<13}{lag:>5}  {rule:<30}{acc:>8.1%}" + "".join(f"{b:>8.1%}" for b in by_loc))
    lr = {(r[0], r[1]): r[3] for r in rows if r[2] == "Lee-Ready"}
    print(f"\n  Lee-Ready on exchange timestamps: {lr[('exchange ts', '0 s')]:.1%} at lag 0 ->"
          f" {lr[('exchange ts', '5 s')]:.1%} with the 5-second convention.")
    print(f"  On vendor timestamps: {lr[('vendor ts', '0 s')]:.1%} at lag 0 ->"
          f" {lr[('vendor ts', '1 s')]:.1%} at 1 s -> {lr[('vendor ts', '5 s')]:.1%} at 5 s.")
    print("  The right lag is a property of your CLOCK, not of the rule. Midpoint trades are")
    print("  the floor: the quote rule is silent there and the tick rule is WORSE than a coin")
    print("  flip, because a midpoint print after a trade at the touch is a downtick for a buy.")

    # ---- bulk volume classification, at the bar level --------------------
    best = keep[("exchange ts", 0.0)]
    sz = trades["sz"].to_numpy(); px = trades["px"].to_numpy(); day = trades["day"].to_numpy()
    thr = 20_000.0
    ids = session_bar_ids(sz, day, thr, N_DAYS_BOOK)
    df = pd.DataFrame({"id": ids, "px": px, "sz": sz, "buy_true": sz * (truth > 0),
                       "buy_lr": sz * (best > 0)})
    g = df.groupby("id")
    vol = g["sz"].sum().to_numpy(); close = g["px"].last().to_numpy()
    dp = np.diff(close, prepend=close[0])
    frac_bvc = norm_cdf(dp / dp.std())
    frac_true = g["buy_true"].sum().to_numpy() / vol
    frac_lr = g["buy_lr"].sum().to_numpy() / vol
    print(f"\n  Bulk volume classification on {len(vol):,} volume bars of {thr:,.0f} shares:"
          f" buy fraction = Phi(dP / sd(dP))")
    print(f"    {'estimate of the bar buy fraction':<36}{'corr w/ truth':>15}{'mean abs err':>14}")
    for name, f in (("BVC (needs no quotes, no sides)", frac_bvc),
                    ("Lee-Ready, exchange ts, lag 0", frac_lr)):
        print(f"    {name:<36}{np.corrcoef(f, frac_true)[0, 1]:>15.3f}"
              f"{np.mean(np.abs(f - frac_true)):>14.3f}")
    vpin = pd.Series(np.abs(2 * frac_bvc - 1.0)).rolling(50).mean()
    print(f"  VPIN mechanics (|buy - sell| / V over a 50-bar window): mean {vpin.mean():.3f},"
          f" max {vpin.max():.3f} - a number,")
    print("  not a crash forecast. BVC's accuracy is capped by how much of the bar price change")
    print("  the order flow explains, which is exactly what you do not know on real data.")
    return keep


# ------------------------------------------------------------------ part 3 ---
def part3_spreads(trades: pd.DataFrame, quotes: pd.DataFrame) -> None:
    print("\n\nPART 3  quoted, effective, realized spread and price impact")
    print("-" * 78)
    qt = quotes["t"].to_numpy(); qb = quotes["bid"].to_numpy(); qa = quotes["ask"].to_numpy()
    qmid = 0.5 * (qb + qa)
    t = trades["t"].to_numpy(); px = trades["px"].to_numpy(); q = trades["side"].to_numpy()
    sz = trades["sz"].to_numpy(); day = trades["day"].to_numpy()
    idx0 = prevailing(qt, t, 0.0); ok = idx0 >= 0
    mid0 = qmid[idx0]
    qs = []
    for d in range(N_DAYS_BOOK):                          # time-weighted quoted spread
        m = (qt >= d * 86400.0) & (qt < d * 86400.0 + SESSION)
        w = np.diff(np.append(qt[m], d * 86400.0 + SESSION))
        qs.append(float(np.sum((qa[m] - qb[m]) * w) / w.sum()))
    quoted = float(np.mean(qs))
    print(f"  time-weighted quoted spread: ${quoted:.4f} = {quoted / px.mean() * BPS:.2f} bps"
          f" (tick = ${TICK})")
    eff = 2.0 * q * (px - mid0)
    print(f"  effective spread 2q(p - mid): mean ${eff[ok].mean():.4f}, share-weighted"
          f" ${np.average(eff[ok], weights=sz[ok]):.4f}")
    print(f"\n  {'horizon':<10}{'realized $':>12}{'impact $':>10}{'impact bps':>12}")
    for label, delta in (("1 s", 1.0), ("30 s", 30.0), ("5 min", 300.0)):
        keep = ok & ((t - day * 86400.0) < SESSION - delta)
        mid1 = qmid[np.searchsorted(qt, t + delta, side="right") - 1]
        real = 2.0 * q * (px - mid1); imp = 2.0 * q * (mid1 - mid0)
        print(f"  {label:<10}{real[keep].mean():>12.4f}{imp[keep].mean():>10.4f}"
              f"{imp[keep].mean() / px.mean() * BPS:>12.2f}")
    delta = 300.0
    keep = ok & ((t - day * 86400.0) < SESSION - delta)
    mid1 = qmid[np.searchsorted(qt, t + delta, side="right") - 1]
    real = 2.0 * q * (px - mid1); imp = 2.0 * q * (mid1 - mid0)
    buckets = [("odd lot 1-99", 1, 99), ("100", 100, 100), ("200-400", 200, 400),
               ("500-900", 500, 900), ("1,000+", 1000, 10 ** 9)]
    print(f"\n  by trade size, 5-minute horizon (planted: permanent impact linear in size; the book"
          f" is walked past ~{DEPTH_PER_LEVEL} sh)")
    print(f"  {'size':<16}{'n':>8}{'effective':>11}{'realized':>10}{'impact':>9}{'impact bps':>12}")
    print("  " + "-" * 66)
    last = None
    for name, lo, hi in buckets:
        m = keep & (sz >= lo) & (sz <= hi)
        last = (eff[m].mean(), real[m].mean(), imp[m].mean())
        print(f"  {name:<16}{m.sum():>8,}{last[0]:>11.4f}{last[1]:>10.4f}{last[2]:>9.4f}"
              f"{last[2] / px.mean() * BPS:>12.2f}")
    print("\n  effective - realized = impact, per trade, by construction. The size table recovers")
    print("  the PLANTED dependence - a check on the estimator, not evidence about any market.")
    print(f"  Realized spread at 1,000+ shares is ${last[1]:.4f}: the liquidity provider's half-spread")
    print("  is consumed by the permanent impact of size, while the walked ticks are temporary")
    print("  and come back within the horizon. The reversion test in execution-cost-analysis is")
    print("  this same decomposition seen from the taker's side: what reverts was temporary")
    print("  impact, what stays was permanent.")


# ------------------------------------------------------------------ part 4 ---
def part4_impact(trades: pd.DataFrame, quotes: pd.DataFrame, lr: dict, lambdas: np.ndarray,
                 stream_a: dict) -> None:
    print("\n\nPART 4  Kyle's lambda, order-flow imbalance, Amihud")
    print("-" * 78)
    qt = quotes["t"].to_numpy(); qb = quotes["bid"].to_numpy(); qa = quotes["ask"].to_numpy()
    qbs = quotes["bsz"].to_numpy(); qas = quotes["asz"].to_numpy(); qmid = 0.5 * (qb + qa)
    t = trades["t"].to_numpy(); sz = trades["sz"].to_numpy(); q = trades["side"].to_numpy()
    day = trades["day"].to_numpy()
    width = 300.0
    n_iv = int(SESSION // width)
    iv = day * n_iv + ((t - day * 86400.0) // width).astype(int)
    e = np.zeros(len(qt))                                 # OFI per quote update
    db = np.diff(qb); da = np.diff(qa)
    e[1:] = ((db >= 0) * qbs[1:] - (db <= 0) * qbs[:-1]
             - (da <= 0) * qas[1:] + (da >= 0) * qas[:-1])
    qday = (qt // 86400.0).astype(int)
    q_iv = qday * n_iv + np.minimum(((qt - qday * 86400.0) // width).astype(int), n_iv - 1)

    variants = {"true sides": q, "LR exch 0 s": lr[("exchange ts", 0.0)],
                "LR vendor 0 s": lr[("vendor ts", 0.0)], "LR exch 5 s": lr[("exchange ts", 5.0)]}
    rows = []
    for d in range(N_DAYS_BOOK):
        ivs = np.arange(d * n_iv, (d + 1) * n_iv)
        edges = d * 86400.0 + np.arange(n_iv + 1) * width
        dmid = np.diff(qmid[np.searchsorted(qt, edges, side="right") - 1])
        ofi = pd.Series(e).groupby(q_iv).sum().reindex(ivs, fill_value=0.0).to_numpy()
        row = {"day": d, "planted": lambdas[d]}
        for name, s in variants.items():
            flow = pd.Series(s * sz).groupby(iv).sum().reindex(ivs, fill_value=0.0).to_numpy()
            row[name] = ols(dmid, flow)
        row["OFI"] = ols(dmid, ofi)
        rows.append(row)
    print(f"  {n_iv} five-minute intervals per session; d(mid) regressed on net signed volume.")
    print("  all lambdas in 1e-5 $/share; se in the same units\n")
    print(f"  {'day':<4}{'planted':>8}{'lambda^ (se)':>15}{'R2':>6}{'LR exch 0s':>12}"
          f"{'LR vend 0s':>12}{'LR exch 5s':>12}{'OFI coef':>10}{'OFI R2':>8}")
    print("  " + "-" * 87)
    for r in rows:
        b, se, r2 = r["true sides"]
        print(f"  {r['day']:<4}{r['planted'] * 1e5:>8.1f}{b * 1e5:>9.2f} ({se * 1e5:.2f}){r2:>6.2f}"
              f"{r['LR exch 0 s'][0] * 1e5:>12.2f}{r['LR vendor 0 s'][0] * 1e5:>12.2f}"
              f"{r['LR exch 5 s'][0] * 1e5:>12.2f}{r['OFI'][0] * 1e5:>10.2f}{r['OFI'][2]:>8.2f}")
    planted = np.array([r["planted"] for r in rows])
    b_true = np.array([r["true sides"][0] for r in rows])
    se_true = np.array([r["true sides"][1] for r in rows])
    within = np.mean(np.abs(b_true - planted) <= 2 * se_true)
    print(f"\n  planted lambda inside lambda^ +/- 2 se on {within:.0%} of days;"
          f" mean lambda^/planted = {np.mean(b_true / planted):.3f}")
    ratios = {}
    for name in ("LR exch 0 s", "LR vendor 0 s", "LR exch 5 s"):
        est = np.array([r[name][0] for r in rows])
        ratios[name] = (np.mean(est / planted), est.min())
        print(f"  with {name:<14} sides instead of true sides: mean lambda^/planted ="
              f" {ratios[name][0]:.3f}, min lambda^ = {est.min() * 1e5:.2f}")
    print("  Classification error is not random noise in the regressor. Under the vendor clock")
    print("  the flipped sides are precisely the trades that moved the quote, so lambda^ does")
    print("  not merely shrink - it changes sign on the high-lambda days.")
    print(f"  OFI R2 mean {np.mean([r['OFI'][2] for r in rows]):.2f} vs signed volume"
          f" {np.mean([r['true sides'][2] for r in rows]):.2f}. Depth changes in this simulator")
    print("  carry no information by construction, so this shows the computation (L1 quotes")
    print("  only, no trade sides needed) and nothing about OFI's edge on real books.")

    # ---- Amihud and a trades-only Kyle on the 40-session stream ---------------
    tr = stream_a["trades"]; lam_a = stream_a["lambdas"]
    t2 = tr["t"].to_numpy(); px2 = tr["px"].to_numpy(); sz2 = tr["sz"].to_numpy()
    q2 = tr["side"].to_numpy(); day2 = tr["day"].to_numpy()
    amihud = np.zeros(N_DAYS_TRADES); kyle = np.zeros(N_DAYS_TRADES)
    for d in range(N_DAYS_TRADES):
        m = day2 == d
        amihud[d] = abs(math.log(px2[m][-1] / px2[m][0])) / float((px2[m] * sz2[m]).sum())
        iv2 = ((t2[m] - d * 86400.0) // width).astype(int)
        last = pd.Series(px2[m]).groupby(iv2).last()
        flow = pd.Series(q2[m] * sz2[m]).groupby(iv2).sum()
        kyle[d] = ols(np.diff(last.to_numpy()), flow.to_numpy()[1:])[0]
    rk = pd.DataFrame({"planted": lam_a, "kyle": kyle, "amihud": amihud}).rank().corr()
    print(f"\n  Amihud |r_day| / $volume on the {N_DAYS_TRADES}-session trades-only stream:"
          f" mean {amihud.mean() * 1e9:.2f} per $bn")
    print(f"  rank correlation with the planted lambda across {N_DAYS_TRADES} days:"
          f" Kyle (trade prices) {rk.iloc[0, 1]:.2f}, Amihud {rk.iloc[0, 2]:.2f}")
    print("  Amihud needs only daily bars, which is its whole appeal, and one day of it is one")
    print("  noisy draw of |flow| x lambda. Average it over months before ranking anything.")


if __name__ == "__main__":
    print(f"microstructure_measures.py  seed {SEED}  numpy {np.__version__}  pandas {pd.__version__}\n")
    res = part1_bars()
    sim = simulate_book()
    trades, quotes = sim["trades"], sim["quotes"]
    print(f"\n\nbook stream for parts 2-4: {N_DAYS_BOOK} sessions, {len(trades):,} trades,"
          f" {len(quotes):,} quote updates, seed {SEED}")
    print(f"planted: lambda in {{{', '.join(f'{x * 1e5:.1f}' for x in sorted(set(LAMBDAS)))}}}e-5"
          f" $/share by day; order-flow persistence {PERSIST}; tick ${TICK}")
    lr = part2_classification(trades, quotes)
    part3_spreads(trades, quotes)
    part4_impact(trades, quotes, lr, sim["lambdas"], res["_streamA"])
    print("\nRule: score every microstructure estimator on data where you planted the answer")
    print("      before you trust it on data where you did not.")
